 private final class ActionButton extends Button{private final String symbol;private final Paint pen=new Paint(Paint.ANTI_ALIAS_FLAG);ActionButton(String icon){super(MultiViewActivity.this);symbol=icon;}@Override protected void onDraw(Canvas canvas){super.onDraw(canvas);canvas.save();canvas.translate(getWidth()/2f,getHeight()/2f);canvas.scale(dp(26)/26f,dp(26)/26f);pen.setColor(Color.WHITE);pen.setStrokeWidth(2.3f);pen.setStrokeCap(Paint.Cap.ROUND);pen.setStyle(Paint.Style.STROKE);if("+".equals(symbol)){canvas.drawLine(-9,0,9,0,pen);canvas.drawLine(0,-9,0,9,pen);}else if("×".equals(symbol)){canvas.drawLine(-8,-8,8,8,pen);canvas.drawLine(-8,8,8,-8,pen);}else if("▦".equals(symbol)){canvas.drawRoundRect(-10,-8,10,8,2,2,pen);canvas.drawLine(0,-8,0,8,pen);canvas.drawLine(-10,0,10,0,pen);}else if("Ⅱ".equals(symbol)){pen.setStyle(Paint.Style.FILL);canvas.drawRoundRect(-8,-10,-3,10,1,1,pen);canvas.drawRoundRect(3,-10,8,10,1,1,pen);}else if("▶".equals(symbol)){pen.setStyle(Paint.Style.FILL);Path p=new Path();p.moveTo(-6,-10);p.lineTo(10,0);p.lineTo(-6,10);p.close();canvas.drawPath(p,pen);}else{Path p=new Path();p.moveTo(-10,-4);p.lineTo(-5,-4);p.lineTo(2,-10);p.lineTo(2,10);p.lineTo(-5,4);p.lineTo(-10,4);p.close();canvas.drawPath(p,pen);if("♫".equals(symbol)){canvas.drawArc(0,-9,14,9,-60,120,false,pen);}else canvas.drawLine(5,-7,12,7,pen);}canvas.restore();}}
