 private final class LayoutTile extends Button{final int mode;final String label;final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);LayoutTile(int m,String text){super(MultiViewActivity.this);mode=m;label=text;setText("");setContentDescription(text);}@Override protected void onDraw(Canvas c){super.onDraw(c);MultiViewPolicy preview=new MultiViewPolicy();preview.layout(mode);float margin=dp(14),w=getWidth()-2*margin,h=Math.min(dp(82),getHeight()-dp(48));paint.setStyle(Paint.Style.FILL);for(int n=0;n<preview.visible();n++){float[] r=preview.rectangle(n);paint.setColor(multiAccent());c.drawRoundRect(margin+w*r[0]+2,dp(10)+h*r[1]+2,margin+w*(r[0]+r[2])-2,dp(10)+h*(r[1]+r[3])-2,dp(3),dp(3),paint);}paint.setColor(Color.WHITE);paint.setTextAlign(Paint.Align.CENTER);paint.setTextSize(dp(17));c.drawText(label,getWidth()/2f,getHeight()-dp(12),paint);}}
